-- Setup G · Addon Farm Breeding · Draft Modal Config: header + 3 detail (@STEM_DRAFT_MODALD/D2/D3). Entity SL: STEM_DRAFT_MODAL.
-- _Detail* = baris detail digabung (baris dipisah '¦', kolom '^', urut LineId): dibandingkan antar DB, tidak dikirim sebagai field; dipecah lagi saat baris BARU dibuat.
SELECT H."Code" AS "_key", H."Code", H."Name", H."U_ObjType", H."U_EnableForeignCurrency", H."U_ShowSummary", H."U_IsActive", H."U_Description",
       (SELECT STRING_AGG(IFNULL(CAST(D."U_FieldName" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldLabel" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldType" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldOrder" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldWidth" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_IsVisible" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_CssClass" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldGroup" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_TextAlign" AS NVARCHAR(500)),''), '¦' ORDER BY D."LineId") FROM "@STEM_DRAFT_MODALD" D WHERE D."Code" = H."Code") AS "_DetailH",
       (SELECT STRING_AGG(IFNULL(CAST(D."U_FieldName" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldLabel" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldType" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldOrder" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldWidth" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_IsVisible" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_CssClass" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_ForeignCurrencyField" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_UseCurrencyDecimals" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_TextAlign" AS NVARCHAR(500)),''), '¦' ORDER BY D."LineId") FROM "@STEM_DRAFT_MODALD2" D WHERE D."Code" = H."Code") AS "_DetailI",
       (SELECT STRING_AGG(IFNULL(CAST(D."U_FieldName" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldLabel" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldType" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldOrder" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_FieldWidth" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_IsVisible" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_CssClass" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_ForeignCurrencyField" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_UseCurrencyDecimals" AS NVARCHAR(500)),'') || '^' || IFNULL(CAST(D."U_TextAlign" AS NVARCHAR(500)),''), '¦' ORDER BY D."LineId") FROM "@STEM_DRAFT_MODALD3" D WHERE D."Code" = H."Code") AS "_DetailS"
FROM "@STEM_DRAFT_MODAL" H
ORDER BY H."Code"
